export function mapLanguageText(text: string, language: AppLanguage) {
  const match = text.match(/^(\s*)([\s\S]*?)(\s*)$/);
  if (!match) return text;
  const [, leading, phrase, trailing] = match;
  if (language !== 'en') {
    const count = phrase.match(/^(\d+) (photos?|files?|guides?|links?|views?)$/i);
    if (count) {
      const unit = count[2].toLowerCase().replace(/s$/, '');
      const tamilUnits: Record<string, [string, string]> = {
        photo: ['புகைப்படம்', 'புகைப்படங்கள்'], file: ['கோப்பு', 'கோப்புகள்'], guide: ['வழிகாட்டி', 'வழிகாட்டிகள்'],
        link: ['இணைப்பு', 'இணைப்புகள்'], view: ['பார்வை', 'பார்வைகள்'],
      };
      const teluguUnits: Record<string, [string, string]> = {
        photo: ['ఫోటో', 'ఫోటోలు'], file: ['ఫైల్', 'ఫైళ్లు'], guide: ['గైడ్', 'గైడ్‌లు'], link: ['లింక్', 'లింక్‌లు'], view: ['వీక్షణ', 'వీక్షణలు'],
      };
      const malayalamUnits: Record<string, [string, string]> = {
        photo: ['ഫോട്ടോ', 'ഫോട്ടോകൾ'], file: ['ഫയൽ', 'ഫയലുകൾ'], guide: ['ഗൈഡ്', 'ഗൈഡുകൾ'], link: ['ലിങ്ക്', 'ലിങ്കുകൾ'], view: ['കാഴ്ച', 'കാഴ്ചകൾ'],
      };
      const units = language === 'ta' ? tamilUnits : language === 'te' ? teluguUnits : malayalamUnits;
      return `${leading}${count[1]} ${units[unit][count[1] === '1' ? 0 : 1]}${trailing}`;
    }
    const viewLine = phrase.match(/^(\d+) views · (.+)$/i);
    if (viewLine) {
      const label = language === 'ta' ? 'பார்வைகள்' : language === 'te' ? 'వీక్షణలు' : 'കാഴ്ചകൾ';
      return `${leading}${viewLine[1]} ${label} · ${viewLine[2]}${trailing}`;
    }
  }
  return `${leading}${languageMapper[language][phrase] ?? phrase}${trailing}`;
}
